		last := lastTopLevelClauseWord(cypher)
		if last == "WITH" {
			if scope, ok := stripWithEmbeddingSuffix(cypher); ok {
				switch lastTopLevelClauseWord(scope) {
				case "", "UNWIND", "MATCH", "OPTIONAL", "WITH", "CALL", "LET", "FILTER", "FOR":
				default:
					last = ""
				}
			}
		}
